  function codingContext(prefix){if(prefix==='correction'){const item=correctionItem(),id='cor:'+item.sourceId+':'+item.taskIndex,history=corrections.history.filter(x=>x.sourceId===item.sourceId&&Number(x.taskIndex)===item.taskIndex),last=history.at(-1);return {key:'correction:'+id,id,task:item.task,code:val('correction:'+id+':code',last?.code||item.original),input:val('correction:'+id+':input',last?.inputData||item.inputData||'')};}const a=active();return {key:'task:'+a.attempt.id,id:a.attempt.id,task:a.task,code:val('task:'+a.attempt.id+':code',a.attempt.code||''),input:val('task:'+a.attempt.id+':input',a.attempt.inputData||'')};}
  function execute(code,input,testing=false){if(location.protocol==='file:')return Promise.reject(Error(t('START_WINDOWS.cmd арқылы ашыңыз: http://127.0.0.1:8765','Откройте через START_WINDOWS.cmd: http://127.0.0.1:8765')));return new Promise((resolve,reject)=>{const worker=new Worker('python-worker.js');runtime=worker;let timer=setTimeout(()=>finish(Error(t('Python жүктелмеді. Интернетті тексеріңіз.','Python не загрузился. Проверьте интернет.'))),120000);function finish(error,result){clearTimeout(timer);worker.terminate();runtime=null;error?reject(error):resolve(result);}worker.onmessage=({data})=>{if(data.type==='ready'){clearTimeout(timer);timer=setTimeout(()=>finish(null,{ok:false,output:t('Орындау уақыты аяқталды. Цикл шартын тексеріңіз.','Время выполнения истекло. Проверьте условие цикла.')}),8000);}else finish(null,data);};worker.onerror=e=>finish(Error(e.message));worker.postMessage({code,input,testing});});}
  async function runCode(prefix){const c=codingContext(prefix),result=await execute(c.code,c.input);drafts.set(c.key+':output',result.output);if(prefix!=='correction'&&active().attempt.status==='in_progress')await saveCode(active().attempt);if(!result.ok)toast(t('Қате табылды. Хабарды оқып, қадамдық көрініспен тексер.','Найдена ошибка. Прочитай сообщение и проверь код по шагам.'),true);}
  async function checkCode(prefix){const c=codingContext(prefix),testData=await api('getTaskTests',{taskId:c.task.id});if(!testData.tests.length){toast(t('Бұл тапсырмаға автоматты мысалдар қосылмаған.','Для этого задания проверочные примеры не добавлены.'));return;}const outputs=[];for(const test of testData.tests){const r=await execute(c.code,test.input,true);outputs.push({output:r.output,error:!r.ok});}const report=await api('checkTaskOutputs',{taskId:c.task.id,outputs});checkResults.set(c.key,report);}
  function csvDownload(name,rows){const text='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,x=>"'"+x).replace(/"/g,'""')+'"').join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
