  function stageFields(at){const s=steps[step][0],entry=ped.evidence.find(x=>x.attemptId===at.id&&x.kind==='stage'&&x.step===s),fields=pd(entry).fields||[],def=pm(active()?.task)?.prompts?.[s]||window.CT_PEDAGOGY.steps[s];
    return `<div class="structured">${(def?.[lang]||[]).map((prompt,i)=>`<label class="field">${esc(prompt)}${at.status==='in_progress'&&!active()?.archived?area('ev:'+at.id+':'+s+':'+i,fields[i]||''):`<div class="answer">${esc(fields[i]||'—')}</div>`}</label>`).join('')}<p class="compact muted">${t('Толтыру — дұрыс жауаптың дәлелі емес. Мазмұнын мұғалім өлшемдермен бағалайды.','Заполнение не означает правильность ответа. Содержание оценивает учитель по критериям.')}</p></div>`;
  }
  const oldTaskView=taskView;
  taskView=function(){const at=active()?.attempt;let html=oldTaskView();if(!at)return html;html=goalBox(active().task)+html;
    if(String(at.pedagogyVersion)==='9')html=html.replace(/<label class="field">(?:Ойлау жазбасы|Ход рассуждений)[\s\S]*?<\/label>/,stageFields(at));
    return html;
  };
  const oldTasksView=tasksView;
  tasksView=function(){return `<div class="note">${t('Есептер жеңілден күрделіге қарай реттелген. Тапсырманы ашып, мақсаты мен қолдауын көр.','Задачи расположены от простых к сложным. Открой задание, чтобы увидеть цель и поддержку.')}</div>`+oldTasksView();};
  const oldSaveTask=saveTask;
  saveTask=async function(){const at=active()?.attempt;if(at?.status==='in_progress'&&String(at.pedagogyVersion)==='9'){
    const s=steps[step][0],old=pd(ped.evidence.find(x=>x.attemptId===at.id&&x.step===s&&x.kind==='stage')).fields||[];
    const fields=[0,1].map(i=>val('ev:'+at.id+':'+s+':'+i,old[i]||''));
    await api('saveLearningEvidence',{attemptId:at.id,step:s,fields});
    drafts.set('step:'+at.id+':'+s,fields.every(x=>x.trim())?fields.map((x,i)=>(i+1)+'. '+x).join('\n\n'):'');
    const id=at.id+':'+s;ped.evidence=ped.evidence.filter(x=>x.id!==id);ped.evidence.push({id,attemptId:at.id,kind:'stage',step:s,detailsJson:JSON.stringify({fields})});
  }await oldSaveTask();};
  const oldSaveStep=actions['save-step'];
  actions['save-step']=async()=>{const at=active().attempt;if(String(at.pedagogyVersion)==='9'){
    await saveTask();if(!val('step:'+at.id+':'+steps[step][0]).trim())throw Error(t('Екі сұраққа да жауап бер.','Ответь на оба вопроса.'));
  }await oldSaveStep();};
  function latestRun(id){const at=active()?.attempt;return ped.evidence.filter(x=>x.attemptId===id&&x.kind==='run'&&pd(x).completed&&(!at||sameRun(x,at))).at(-1);}
  const oldPanel=codePanel;
  codePanel=function(at,info,locked=false,prefix='task'){let html=oldPanel(at,info,locked,prefix);
    if(prefix==='task'&&!locked&&String(at.pedagogyVersion)==='9'){
      const r=latestRun(at.id)||ped.evidence.filter(x=>x.attemptId===at.id&&x.kind==='run'&&pd(x).completed).at(-1),d=pd(r),key='task:'+at.id;
      html=html.replace('<div class="row">',`<label class="field">${t('Орындамай тұрып: осы кіріс үшін қандай нәтиже күтесің?','До запуска: какой результат ожидаешь при этом вводе?')}${area(key+':prediction')}</label><div class="row">`);
      if(r)html+=`<div class="card reflection-card" data-reflection-id="${r.id}"><p data-stale-note class="note" hidden>${t("Код не кіріс өзгерген. Бұл — алдыңғы орындаудың жазбасы. Жаңа болжам жазып, қайта орында.","Код или ввод изменён. Это запись предыдущего запуска. Сделай новый прогноз и выполни код.")}</p><h3>${t('Болжамды нәтижемен салыстыр','Сравни прогноз с результатом')}</h3><p>${t('Сақталған болжам','Сохранённый прогноз')}: ${esc(d.prediction)}</p><pre class="console">${esc(d.output)}</pre><label class="field">${t('Қайсысы сәйкес келді, қайсысы өзгерді?','Что совпало, а что отличалось?')}${area('compare:'+r.id,d.comparison||'')}</label><label class="field">${t('Кодтың нақты жолына сүйеніп себебін түсіндір.','Объясни причину, ссылаясь на конкретную строку кода.')}${area('explain:'+r.id,d.explanation||'')}</label>${action('save-reflection',t('Салыстыруды сақтау','Сохранить сравнение'),'',`data-id="${r.id}"`)}</div>`;
    }return html;
  };
  async function predictedRun(prefix,mode){const c=codingContext(prefix);if(prefix==='correction'||String(active().attempt.pedagogyVersion)!=='9'||active().attempt.status!=='in_progress'){await runCodeOriginal(prefix);return c;}
    const prediction=val(c.key+':prediction').trim();if(!prediction)throw Error(t('Алдымен болжам жаз.','Сначала запиши прогноз.'));
    const record=await api('startPrediction',{attemptId:c.id,code:c.code,input:c.input,prediction,mode:liveStates.get(c.key)?.usedLive?'live-assisted:'+mode:mode,hints:hintLevels.get(c.key)||0});
    const result=await execute(c.code,c.input);drafts.set(c.key+':output',result.output);await saveCode(active().attempt);
    await api('completePrediction',{id:record.id,phase:'result',output:result.output});ped=await api('pedagogyWorkspace');drafts.delete(c.key+':prediction');return c;
  }
  const runCodeOriginal=runCode;
  actions['run-code']=b=>predictedRun(b.dataset.prefix,'run');
  actions['visualize']=async b=>{const c=await predictedRun(b.dataset.prefix,'visual');CodeThinkVisual.open({title:taskInfo(c.task).title,code:c.code,input:c.input,readOnly:true,scene:taskInfo(c.task).scene,lang});};
  const oldCheck=actions['check-code'];
  actions['check-code']=async b=>{if(b.dataset.prefix==='task'&&String(active().attempt.pedagogyVersion)==='9'&&!latestRun(active().attempt.id))throw Error(t('Алдымен өз мысалыңа болжам жасап, орында.','Сначала сделай прогноз и запусти свой пример.'));await oldCheck(b);};
  actions['save-reflection']=async b=>{await api('completePrediction',{id:b.dataset.id,phase:'reflection',comparison:val('compare:'+b.dataset.id),explanation:val('explain:'+b.dataset.id)});ped=await api('pedagogyWorkspace');toast(t('Салыстыру сақталды.','Сравнение сохранено.'));};
  const oldStudentView=studentView;
  studentView=()=>page==='transfer'?nav()+transferView():page==='probe'?nav()+probeView():oldStudentView();
  function transferView(){return `<h1>${t('Жаңа жағдайда қолдану','Применение в новой ситуации')}</h1><div class="note">${t('Оқу жұмысын тапсырғаннан кейін жаңа есепті көмексіз шешіп көр. 7 күннен соң басқа есеп ашылады. Бұл бөлімде кодты орындау, көмек және визуализация жоқ. Сырттан алған көмекті міндетті түрде көрсет.','После сдачи учебной работы реши новую задачу без подсказок. Через 7 дней откроется другая задача. Здесь нет запуска кода, подсказок и визуализации. Обязательно укажи помощь, полученную извне.')}</div><div class="task-grid">${workspace.assignments.filter(a=>['submitted','graded'].includes(a.attempt?.status)&&pm(a.task)).map(a=>{
    const probes=ped.probes.filter(x=>x.attemptId===a.attempt.id),first=probes.find(x=>x.phase==='immediate'),ready=first?.submittedAt&&Date.now()-new Date(first.submittedAt)>=7*86400000;
    return `<article class="card"><h3>${esc(taskInfo(a.task).title)}</h3>${['immediate','delayed'].map(phase=>{const p=probes.find(x=>x.phase===phase);return `<p>${phase==='immediate'?t('Алғашқы бекіту','Первичная проверка'):t('7 күннен кейін','Через 7 дней')}: ${p?statusText(p.status):'—'}</p>${p||phase==='immediate'||ready?action('open-probe',t('Ашу','Открыть'),'',`data-attempt="${a.attempt.id}" data-phase="${phase}"`):`<small>${first?.submittedAt?date(new Date(new Date(first.submittedAt).getTime()+7*86400000).toISOString()):t('Алғашқы бекітуден кейін','После первичной проверки')}</small>`}`;}).join('')}</article>`;
  }).join('')||empty(t('Алдымен оқу тапсырмасын аяқта.','Сначала заверши учебное задание.'))}</div>`;}
  function probeView(){const p=ped.probes.find(x=>x.id===probeId);if(!p)return transferView();const prompt=JSON.parse(p.promptJson),locked=p.status!=='in_progress';
    return `<h1>${t('Өздігінен шешіп көр','Попробуй решить самостоятельно')}</h1><article class="card stack"><p>${esc(prompt[lang])}</p>${[['answer','Код немесе толық алгоритм','Код или полный алгоритм'],['reason','Неге бұл шешім жаңа жағдайға сай келеді? Мысалмен дәлелде.','Почему решение подходит к новой ситуации? Обоснуй примером.'],['help','Қандай көмек алдың? Алмасаң, «көмексіз» деп жаз.','Какую помощь ты получил? Если никакой, напиши «без помощи».']].map(([key,kk,ru])=>`<label class="field">${t(kk,ru)}${locked?`<div class="answer">${esc(p[key])}</div>`:area('probe:'+p.id+':'+key,p[key])}</label>`).join('')}${!locked?`<div class="row">${action('save-probe',t('Жобаны сақтау','Сохранить черновик'))}${action('submit-probe',t('Мұғалімге жіберу','Отправить учителю'),'primary')}</div>`:`<p>${esc(p.scoresJson||'')} ${esc(p.feedback||'')}</p>`}${action('page',t('Бекіту тізіміне','К списку проверок'),'','data-page="transfer"')}</article>`;
  }
  actions['open-probe']=async b=>{const p=await api('startTransfer',{attemptId:b.dataset.attempt,phase:b.dataset.phase});probeId=p.id;ped=await api('pedagogyWorkspace');page='probe';};
  async function saveProbe(submit){const p=ped.probes.find(x=>x.id===probeId);await api('saveTransfer',{id:p.id,answer:val('probe:'+p.id+':answer',p.answer),reason:val('probe:'+p.id+':'+ 'reason',p.reason),help:val('probe:'+p.id+':help',p.help),submit});ped=await api('pedagogyWorkspace');toast(t('Сақталды.','Сохранено.'));}
  actions['save-probe']=()=>saveProbe(false);actions['submit-probe']=()=>saveProbe(true);
  const oldResults=resultsView;resultsView=()=>`<div class="note">${t('Диагностика айырмасы — сипаттамалық көрсеткіш. Тапсырмалардың тең қиындығы мен өткізу жағдайы тексерілмесе, оны әдістің дәлелденген әсері деп айтуға болмайды. Өзіндік бекіту нәтижесі бөлек бағаланады.','Разница диагностик — описательный показатель. Без проверки сопоставимости заданий и условий её нельзя считать доказанным эффектом метода. Результат самостоятельного переноса оценивается отдельно.')}</div>`+oldResults();
  const oldMistakes=mistakesView;mistakesView=()=>oldMistakes()+`<div class="note">${t('Түзету бағасы білімнің жаңа есепке ауысқанын әлі дәлелдемейді. Оқу тапсырмасынан кейін «Жаңа есеппен бекіту» бөлімін орында.','Оценка исправления ещё не доказывает перенос знаний. После учебной задачи выполни раздел «Перенос на новую задачу».')}</div>`;
  const oldTeacher=teacherView;
  teacherView=()=>oldTeacher()+(teacherTab==='pedagogy'?teacherPedagogy():'');
  function rubric(){return `<div class="note"><strong>${t('Бекіту рубрикасы: шешім · түсіндіру · жаңа жағдайға бейімдеу (әрқайсысы 0–3)','Рубрика переноса: решение · объяснение · адаптация к новой ситуации (по 0–3)')}</strong><p>${t('0 — дәлел жоқ/қате; 1 — жартылай, елеулі қате бар; 2 — негізінен дұрыс, ұсақ олқылық бар; 3 — дұрыс, толық және мысалмен негізделген. Мәтін көлеміне балл берілмейді. Көмек туралы жазбаны ескеріңіз.','0 — нет свидетельства/неверно; 1 — частично, существенные ошибки; 2 — в основном верно, небольшие недочёты; 3 — верно, полно и обосновано примером. Объём текста не оценивается. Учитывайте сведения о помощи.')}</p></div>`;}
  function reviewForm(key,title){const r=ped.reviews.find(x=>x.key===key)||{};return `<details class="card"><summary>${esc(title)} · ${r.updatedAt?t('Жазба бар','Есть запись'):t('Тексерілмеген','Не проверено')}</summary><label class="field">${t('Дереккөз: құжат, бөлім/бет, оқу мақсаты','Источник: документ, раздел/страница, учебная цель')}${area('ref:'+key,r.reference||'')}</label><label class="field">${t('Тексеру қорытындысы және қалған шектеулер','Результат проверки и оставшиеся ограничения')}${area('review:'+key,r.note||'')}</label>${action('save-review',t('Тексеру жазбасын сақтау','Сохранить запись проверки'),'',`data-key="${key}"`)}</details>`;}
  function teacherPedagogy(){
    const submitted=ped.probes.filter(x=>x.status!=='in_progress'),reviewed=submitted.filter(x=>x.status==='reviewed'),paired=dashboard.users.filter(u=>['baseline','final'].every(type=>dashboard.attempts.some(a=>a.userId===u.id&&(a.attemptType||'baseline')===type&&a.status==='graded'))).length;
    return `<section class="stack"><h1>${t('Педагогика және дәлелдер','Педагогика и свидетельства')}</h1><div class="grid3"><div class="metric"><small>${t('Екі диагностикасы бағаланған','Оценены обе диагностики')}</small><strong>${paired}</strong></div><div class="metric"><small>${t('Бекіту тапсырылған','Проверок переноса сдано')}</small><strong>${submitted.length}</strong></div><div class="metric"><small>${t('Бекіту бағаланған','Проверок переноса оценено')}</small><strong>${reviewed.length}</strong></div></div><div class="note">${t('Нәтиже — жиналған дерек. Бұл себептік әсердің дәлелі емес. Әдістемелік құралдың толық түпнұсқасы берілмеген: барлық тақырып қамтылды деген тұжырым әлі расталмаған.','Результат — собранные данные, а не доказательство причинного эффекта. Полный оригинал методического пособия не предоставлен: полнота охвата тем ещё не подтверждена.')}</div>${action('evidence-csv',t('Аты-жөнсіз нәтижелерді жүктеу','Скачать результаты без ФИО'))}<a href="teacher-guide.html" target="_blank">${t('Сабақ, сынақ және қорғау нұсқаулығы','Руководство по уроку, апробации и защите')}</a>${rubric()}<h2>${t('Бекіту жұмыстарын бағалау','Оценивание переноса')}</h2>${submitted.map(p=>`<details class="card"><summary>${esc(dashboard.users.find(x=>x.id===p.userId)?.name||'—')} · ${esc(p.sourceKey)} · ${p.phase==='delayed'?t('Кейінгі','Отсроченная'):t('Алғашқы','Первичная')} · ${statusText(p.status)}</summary><p>${esc(JSON.parse(p.promptJson)[lang])}</p><pre class="code-block">${esc(p.answer)}</pre><p>${esc(p.reason)}</p><p>${t('Көмек туралы мәлімет','Сведения о помощи')}: ${esc(p.help)}</p>${[t('Шешім','Решение'),t('Түсіндіру','Объяснение'),t('Бейімдеу','Адаптация')].map((label,i)=>`<label class="field">${label}${scoreField('probe-score:'+p.id+':'+i,JSON.parse(p.scoresJson||'[0,0,0]')[i],3)}</label>`).join('')}<label class="field">${t('Бағаны дәлелдеу','Обоснование оценки')}${area('probe-feedback:'+p.id,p.feedback||'')}</label>${action('grade-probe',t('Бағалау','Оценить'),'primary',`data-id="${p.id}"`)}</details>`).join('')||empty(t('Әзірге тапсырылған бекіту жоқ.','Сданных проверок переноса пока нет.'))}<h2>${t('Ойлау дәлелдері','Свидетельства рассуждения')}</h2>${ped.evidence.map(r=>{const d=pd(r);return `<details class="card"><summary>${esc(dashboard.users.find(x=>x.id===r.userId)?.name||'—')} · ${esc(r.step)} · ${date(r.updatedAt)}</summary>${r.kind==='stage'?(d.fields||[]).map(x=>`<p class="answer">${esc(x)}</p>`).join(''):`<p>${t('Болжам','Прогноз')}: ${esc(d.prediction)}</p><pre class="code-block">${esc(d.code)}</pre><p>${t('Кіріс','Ввод')}: ${esc(d.input)}</p><pre>${esc(d.output||'')}</pre><p>${esc(d.comparison||'')}</p><p>${esc(d.explanation||'')}</p><small>${t('Бағыттаушы көмек деңгейі','Уровень подсказок')}: ${d.hints||0}${String(d.mode||'').startsWith('live-assisted:')?' · '+t('Тікелей көрініс қолданылды','Использован прямой предпросмотр'):''}</small>`}</details>`;}).join('')}<h2>${t('Мазмұн мен өлшеуді тексеру','Проверка содержания и измерения')}</h2>${reviewForm('pilot',t('Сынақ: сынып, мерзім, жағдай, қолдау және шектеулер','Апробация: класс, срок, условия, поддержка и ограничения'))}${[7,8].map(g=>`<details class="card"><summary>${g}: ${t('Бастапқы және қорытынды диагностика','Начальная и итоговая диагностика')}</summary>${content.diagnostics.baseline[g].map((q,i)=>`<h4>${i+1}. ${esc(q[lang].title)}</h4><p>${esc(q[lang].prompt)}</p><p>→ ${esc(content.diagnostics.final[g][i][lang].prompt)}</p>`).join('')}</details>`+reviewForm('diagnostic-'+g,g+': '+t('Салыстырмалылықты тексеру','Проверка сопоставимости'))).join('')}${teacherWS.tasks.filter(pm).map(task=>goalBox(task)+reviewForm(pm(task).sourceKey,taskInfo(task).title)).join('')}</section>`;
  }
