  document.querySelector('.brand').onclick=e=>{e.preventDefault();if(busy)return;transact(async()=>{if(page==='task')await saveTask();if(page==='diagnostic')await saveDiagnostic();page='home';teacherTab='overview';});};
  async function boot(){render();if(token){$('app').innerHTML=`<div class="loading">${t('Кабинет жүктелуде…','Кабинет загружается…')}</div>`;try{const restored=await api('sessionUser');user=restored.user;if(!user.mustChangePassword)await refresh();}catch(e){token='';user=null;sessionStorage.removeItem('ct11-token:code-think-new');toast(e.message,true);}render();}}
  // 11.1: durable, account-scoped drafts, explicit readiness and visible assessment.
  let draftOwner='',draftTimer=null,dirtyDrafts=new Set(),restoredDraft=false,backupPreview=null;
  const draftAllowed=k=>/^(ev:|step:|task:|diag:|cor:|correction:|probe:|compare:|explain:|grade:|feedback:|comment:|cor-grade:|cor-feedback:|probe-score:|probe-feedback:)/.test(k);
  const draftKey=()=>user?'ct11-drafts:code-think-new:'+user.id:'';
  function restoreDrafts(){
    if(!user||draftOwner===user.id)return;draftOwner=user.id;dirtyDrafts=new Set();
    try{const saved=JSON.parse(localStorage.getItem(draftKey())||'null');if(saved&&Date.now()-saved.savedAt<14*86400000){for(const [k,v]of saved.entries||[])if(draftAllowed(k)&&typeof v==='string')drafts.set(k,v);dirtyDrafts=new Set((saved.dirty||[]).filter(draftAllowed));restoredDraft=dirtyDrafts.size>0;}}catch{}
  }
  function persistDrafts(){clearTimeout(draftTimer);draftTimer=null;if(!user)return;
    try{const entries=[...drafts].filter(([k,v])=>draftAllowed(k)&&typeof v==='string');localStorage.setItem(draftKey(),JSON.stringify({savedAt:Date.now(),entries,dirty:[...dirtyDrafts]}));setSaveStatus();}catch{setSaveStatus(t('Браузер жобаны сақтай алмады. «Сақтау» батырмасын қолданыңыз.','Браузер не сохранил черновик. Используйте кнопку сохранения.'));}
  }
  function setSaveStatus(message){const el=$('saveState');if(el)el.textContent=message||(busy?t('Әрекет орындалуда…','Выполняем действие…'):dirtyDrafts.size?t('Жоба осы браузерде сақталды. Базаға жіберу үшін «Сақтау» бас.','Черновик сохранён в браузере. Для записи в базу нажми «Сохранить».'):t('Сақталған жауаптар жүктелді.','Сохранённые ответы загружены.'));}
  function markSaved(prefixes){for(const k of dirtyDrafts)if(prefixes.some(p=>k.startsWith(p)))dirtyDrafts.delete(k);persistDrafts();setSaveStatus(t('Базаға сақталды.','Сохранено в базе.'));}
  function sameRun(r,at){const d=pd(r),key='task:'+at.id;return d.completed&&String(d.code).trim()===String(val(key+':code',at.code||'')).trim()&&String(d.input||'')===String(val(key+':input',at.inputData||''));}
  function currentRun(at){return ped.evidence.filter(r=>r.kind==='run'&&r.attemptId===at.id&&sameRun(r,at)).at(-1);}
  function readiness(at){const run=currentRun(at),d=pd(run),stages=steps.map(s=>{const row=ped.evidence.find(x=>x.attemptId===at.id&&x.kind==='stage'&&x.step===s[0]);return (pd(row).fields||[]).length===2&&pd(row).fields.every(x=>String(x).trim());});return {stages,run,executed:!!run,reflected:!!(run&&String(d.comparison||'').trim()&&String(d.explanation||'').trim())};}
  function readinessView(at){if(at.status!=='in_progress'||active()?.archived)return '';const r=readiness(at);return `<details class="card readiness" ${step===4?'open':''}><summary>${t('Тапсыруға дайындық','Готовность к сдаче')} · ${r.stages.filter(Boolean).length}/5</summary><div class="readiness-items">${steps.map((s,i)=>action('required-step',(r.stages[i]?'✓ ':'○ ')+t(s[1],s[2]),'',`data-step="${i}"`)).join('')}${action('required-step',(r.executed?'✓ ':'○ ')+t('Соңғы код орындалды','Последний код выполнен'),'',`data-step="2"`)}${action('required-step',(r.reflected?'✓ ':'○ ')+t('Салыстыру сақталды','Сравнение сохранено'),'',`data-step="2"`)}</div><p class="compact muted">${t('Код не кіріс өзгерсе, сол нұсқаны қайта орындап, салыстыруды сақта.','После изменения кода или ввода выполни новую версию и сохрани сравнение.')}</p></details>`;}
  function updateEvidenceState(){const at=active()?.attempt;if(!at||page!=='task')return;document.querySelectorAll('[data-reflection-id]').forEach(box=>{const r=ped.evidence.find(r=>r.id===box.dataset.reflectionId),valid=r&&sameRun(r,at);box.classList.toggle('stale-evidence',!valid);const note=box.querySelector('[data-stale-note]');if(note)note.hidden=!!valid;const button=box.querySelector('[data-do="save-reflection"]');if(button)button.disabled=busy||!valid;});}
  const taskBeforeReadiness=taskView;
  taskView=function(){const at=active()?.attempt;let html=taskBeforeReadiness();if(!at)return html;return html.replace('<div class="learning-layout">',readinessView(at)+'<div class="learning-layout">');};
  const saveBeforeDraft=saveTask;
  saveTask=async function(){if(active()?.archived)return;await saveBeforeDraft();const at=active()?.attempt;if(at&&at.status==='in_progress')markSaved(['ev:'+at.id+':'+steps[step][0]+':','step:'+at.id+':'+steps[step][0],...(['E','TH'].includes(steps[step][0])?['task:'+at.id+':code','task:'+at.id+':input']:[])]);};
