  const reflectionBeforeGuard=actions['save-reflection'];
  actions['save-reflection']=async b=>{const at=active()?.attempt,r=ped.evidence.find(r=>r.id===b.dataset.id);if(!at||!r||!sameRun(r,at))throw Error(t('Код не кіріс өзгерді. Қайта орындап, жаңа нәтижені салыстыр.','Код или ввод изменён. Выполни заново и сравни новый результат.'));await reflectionBeforeGuard(b);markSaved(['compare:'+r.id,'explain:'+r.id]);};
  actions['required-step']=async b=>{await saveTask();const target=Number(b.dataset.step),first=readiness(active().attempt).stages.findIndex(x=>!x);step=first>=0&&first<target?first:target;};
  const submitBeforeReadiness=actions['save-step'];
  actions['save-step']=async()=>{const at=active()?.attempt;if(!at)return;await saveTask();const r=readiness(at);if(!r.stages[step])throw Error(t('Осы кезеңнің екі сұрағына жауап бер.','Ответь на два вопроса этого этапа.'));if(step!==4){step++;return;}const missing=r.stages.findIndex(x=>!x);if(missing>=0){step=missing;throw Error(t('Осы кезеңнің екі жауабын толтырып, сақта.','Заполни и сохрани два ответа этого этапа.'));}if(!r.executed||!r.reflected){step=2;throw Error(!r.executed?t('Соңғы код үшін болжам жазып, «Орындау» бас.','Запиши прогноз для последнего кода и нажми «Выполнить».'):t('Нәтижені салыстырып, себебін түсіндір де «Салыстыруды сақтау» бас.','Сравни результат, объясни причину и нажми «Сохранить сравнение».'));}await api('submitTask',{attemptId:at.id});for(const k of [...drafts.keys()])if(k.includes(at.id)){drafts.delete(k);dirtyDrafts.delete(k);}persistDrafts();await refresh();page='tasks';toast(t('Жұмыс тапсырылды.','Работа сдана.'));};
  actions['open-task']=async b=>{activeId=b.dataset.id;const a=active();a.attempt=await api('startTaskAttempt',{assignmentId:activeId});ped=await api('pedagogyWorkspace');if(a.attempt.status!=='in_progress'){for(const k of [...drafts.keys()])if(k.includes(a.attempt.id)){drafts.delete(k);dirtyDrafts.delete(k);}persistDrafts();}step=0;page='task';};
