  const refreshBeforeBundle=refresh;
  refresh=async function(){const data=await api('schoolWorkspace',{view:user?.role==='teacher'?teacherTab:page});if(user.role==='teacher'){dashboard=data.dashboard;teacherWS=data.teacherWS;}else{mine=data.mine;workspace=data.workspace;user=mine.user;workspace.assignments.sort((a,b)=>(pm(a.task)?.rank||999)-(pm(b.task)?.rank||999));}taskTimes=data.timings||[];profileInfo=data.studentProfile||{};teacherProfileInfo=data.teacherProfile||{};purgeJobs=data.purgeJobs||[];if(teacherProfileInfo.user)user=teacherProfileInfo.user;corrections=data.corrections;ped=data.ped;if(data.temporaryPasswords){temporaryState=data.temporaryPasswords;credentials=temporaryState.entries||[];}};
  actions['teacher-tab']=async b=>{teacherTab=b.dataset.tab;await refresh();};
