  const renderBeforeDraft=render;
  render=function(){restoreDrafts();renderBeforeDraft();let el=$('saveState');if(!el){el=document.createElement('div');el.id='saveState';el.className='save-state';el.setAttribute('role','status');$('app').before(el);}el.hidden=!user;setSaveStatus();updateEvidenceState();if(restoredDraft&&user){restoredDraft=false;setSaveStatus(t('Осы браузердегі аяқталмаған жоба қалпына келтірілді.','Незавершённый черновик восстановлен из этого браузера.'));}};
  $('app').addEventListener('input',e=>{const key=e.target.dataset.draft;if(key&&draftAllowed(key)){dirtyDrafts.add(key);clearTimeout(draftTimer);draftTimer=setTimeout(persistDrafts,400);}if(key?.endsWith(':code')||key?.endsWith(':input'))updateEvidenceState();});
  $('app').addEventListener('change',e=>{const key=e.target.dataset.draft;if(key&&draftAllowed(key)){dirtyDrafts.add(key);persistDrafts();}});
