  function transferMetrics(){const probes=(ped.probes?.length?ped.probes:workspace.transferProbes||[]).filter(x=>x.status==='reviewed');const values=probes.map(x=>{try{return JSON.parse(x.scoresJson)[2];}catch{return null;}}).filter(Number.isFinite);return values;}
  function attemptResults(){return `<section class="card assessment-results"><h2>${t('Оқу есептерінің бағалары','Оценки учебных задач')}</h2>${workspace.assignments.map(a=>{const at=a.attempt;return `<details class="result-task"><summary>${esc(taskInfo(a.task).title)} · ${at?.status==='graded'?at.score+'/15':statusText(at?.status)}</summary>${at?`<p>${t('Кезеңдер','Этапы')}: ${(at.steps||[]).filter(x=>x.response).length}/5</p>${steps.map(s=>{const row=(at.steps||[]).find(x=>x.stepCode===s[0]);return `<p><b>${t(s[1],s[2])}</b>: ${at.status==='graded'?(row?.score??'—')+'/3':'—'} · ${esc(row?.feedback||t('Пікір жоқ','Нет комментария'))}</p>`;}).join('')}<p><b>${t('Мұғалімнің қорытынды пікірі','Итоговый комментарий учителя')}</b>: ${esc(at.teacherComment||t('Әзірге пікір жоқ.','Комментария пока нет.'))}</p>`:''}</details>`;}).join('')}</section>`;}
  const resultsBeforeMarks=resultsView;
