  function historyView(){return !(workspace.history||[]).length?'':`<section class="card"><h2>${t('Бұрынғы сыныптардағы оқу тарихы','История обучения в прежних классах')}</h2>${workspace.history.map(a=>`<p>${esc(taskInfo(a.task).title)} · ${a.attempt.status==='graded'?a.attempt.score+'/15':statusText(a.attempt.status)} ${action('history-open',t('Қарау','Посмотреть'),'',`data-id="${a.id}"`)}</p>`).join('')}</section>`;}
