  function backupView(){return `<section class="card"><h2>${t('Оқу деректерінің резерв көшірмесі','Резервная копия учебных данных')}</h2><p>${t('JSON көшірмесі осы Firebase жобасындағы осы мұғалімге арналған. Парольдер мен Firebase Authentication аккаунттары көшірілмейді. Қалпына келтіру тек жоқ жазбаларды қосады; қазіргі деректер алмастырылмайды.','JSON-копия предназначена для этого учителя в этом проекте Firebase. Пароли и аккаунты Firebase Authentication не копируются. Восстановление добавляет только отсутствующие записи, сохраняя текущие данные.')}</p><div class="row">${action('download-backup',t('Резервті JSON жүктеу','Скачать резерв JSON'),'primary')}${action('download-grades',t('Бағаларды CSV жүктеу','Скачать оценки CSV'))}</div><label class="field">${t('Қалпына келтіретін JSON','JSON для восстановления')}<input type="file" id="backupFile" accept=".json,application/json"></label>${action('preview-backup',t('Көшірмені тексеру','Проверить копию'))}${backupPreview?`<div class="note">${t('Қосылатын жазба','Будет добавлено')}: ${backupPreview.summary.ready}; ${t('Сақталатын қазіргі жазба','Текущих записей сохранится')}: ${backupPreview.summary.skipped}. ${action('restore-backup',t('Жоқ жазбаларды қалпына келтіру','Восстановить отсутствующие записи'),'primary')}</div>`:''}</section>`;}
  const teacherBeforeBackup=teacherView;
